<script setup lang="ts">
import { Head, useForm, router } from '@inertiajs/vue3'
import { ref,computed } from 'vue'
import ConfirmDialog from '../../Components/ConfirmDialog.vue'
const props=defineProps<{quotas:{data:any[];total:number};usage:Record<string,{total_bytes:number|null;error?:boolean}>;mediaUsers:any[];totalQuota:number;mediaStatsError:string|null}>()
const form=useForm({user_id:'',max_total_bytes:0,max_file_bytes:0,period:'lifetime'})
const deleting=ref(false),selectedUser=ref('')
const totalUsed=computed(()=>props.mediaUsers.reduce((sum,u)=>sum+Number(u.media_length||0),0))
const totalQuota=computed(()=>Number(props.totalQuota||0))
const totalPercent=computed(()=>totalQuota.value>0?Math.min(100,totalUsed.value/totalQuota.value*100):0)
const bytes=(n:number|null)=>n===null?'نامشخص':n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(2)+' MiB':n+' B'
const percent=(user:string,max:number)=>{const n=props.usage[user]?.total_bytes;if(n===null||n===undefined||max<=0)return 0;return Math.min(100,n/max*100)}
const askDelete=(id:string)=>{selectedUser.value=id;deleting.value=true}
const remove=()=>router.delete('/media/quotas/'+encodeURIComponent(selectedUser.value))
</script>
<template><Head title="مدیا و سهمیه‌ها"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">مدیا و سهمیه‌ها</h1><v-alert v-if="mediaStatsError" type="warning" variant="tonal" class="mb-4">{{ mediaStatsError }}</v-alert><v-row><v-col cols="12"><v-card rounded="xl" class="pa-5 d-flex align-center ga-6"><v-progress-circular :model-value="totalPercent" :size="112" :width="12" color="primary">{{ Math.round(totalPercent) }}%</v-progress-circular><div><div class="text-h6">مصرف کاربران دارای مدیا (حداکثر ۱۰۰ نتیجه)</div><div class="text-body-2">{{ bytes(totalUsed) }} از {{ bytes(totalQuota) }}</div><div class="text-caption text-medium-emphasis">مجموع سهمیه کاربران فهرست‌شده در همین نما</div></div></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5"><v-card-title>تعریف سهمیه کاربر</v-card-title><v-card-text><v-form @submit.prevent="form.post('/media/quotas')"><v-text-field v-model="form.user_id" label="شناسه Matrix کاربر"/><v-text-field v-model.number="form.max_total_bytes" type="number" label="حداکثر مصرف کل (bytes)"/><v-text-field v-model.number="form.max_file_bytes" type="number" label="حداکثر اندازه هر فایل (bytes)"/><v-select v-model="form.period" label="دوره محاسبه" :items="[{title:'بدون بازنشانی',value:'lifetime'},{title:'روزانه',value:'day'},{title:'هفتگی',value:'week'},{title:'ماهانه',value:'month'}]"/><v-btn type="submit" color="primary" block :loading="form.processing">ذخیره سهمیه</v-btn></v-form></v-card-text></v-card></v-col><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5"><v-card-title>مصرف و سهمیه کاربران</v-card-title><v-list><v-list-item v-for="u in mediaUsers" :key="u.user_id" :title="u.displayname ? u.displayname+' · '+u.user_id : u.user_id" :subtitle="bytes(u.media_length)+' · '+u.media_count+' فایل · '+(u.max_total_bytes>0 ? bytes(u.max_total_bytes)+' سقف · '+u.period : 'بدون سقف مصرف')"><template #prepend><v-progress-circular :model-value="u.max_total_bytes>0?Math.min(100,u.media_length/u.max_total_bytes*100):0" :size="48" :width="5" color="primary">{{ u.max_total_bytes>0?Math.round(Math.min(100,u.media_length/u.max_total_bytes*100))+'%' : '∞' }}</v-progress-circular></template><template #append><v-btn v-if="u.max_total_bytes>0||u.max_file_bytes>0" icon="mdi-delete" color="error" variant="text" @click="askDelete(u.user_id)"/></template></v-list-item></v-list><v-alert v-if="!mediaUsers.length" type="info" variant="tonal">مدیایی برای نمایش یافت نشد.</v-alert></v-card></v-col></v-row><ConfirmDialog v-model="deleting" title="حذف سهمیه" message="محدودیت این کاربر از Media Gate حذف می‌شود." danger @confirm="remove"/></v-container></template>
